601	+  /// (`error-taxonomy.md`) correct for the stream path too, without
602	+  /// changing [_mapDioException]/`dioErrorCodeOf` themselves — both are
603	+  /// shared with `RetryInterceptor`, which never sees a stream response at
604	+  /// all (it retries before dio's transformer runs), so widening their
605	+  /// `Map`-only contract isn't needed here. Any failure to drain/decode
606	+  /// (including a non-JSON body) falls back to [_mapDioException]'s own
607	+  /// generic mapping unchanged.
608	+  Future<Failure> _mapStreamDioException(DioException e) async {
609	+    final data = e.response?.data;
610	+    if (data is ResponseBody) {
611	+      try {
612	+        final bytes = await data.stream.expand((chunk) => chunk).toList();
613	+        final decoded = jsonDecode(utf8.decode(bytes, allowMalformed: true));
614	+        if (decoded is Map && decoded['code'] is String) {
615	+          final message = decoded['message'];
616	+          final failure = Failure.fromCode(
617	+            decoded['code'] as String,
618	+            (message is String ? message : null) ?? 'Unknown error',
619	+          );
620	+          if (failure is AuthExpired && !_isAnonKeyOnlyCall(e)) {
621	+            _sessionExpiryNotifier.notifyExpired();
622	+          }
623	+          return failure;
624	+        }
625	+      } catch (_) {
626	+        // Falls through to the generic mapping below — same "never throw"
627	+        // rationale every other decode step in this file already follows.
628	+      }
629	+    }
630	+    return _mapDioException(e);
631	+  }
