713	+import 'presentation/cubit/chat_cubit.dart';
714	+
715	+/// The `chat_sessions`/`chat_messages` Hive box names — two boxes (Code
716	+/// Map: "Hive box cache for `listSessions`/`listMessages`"), mirroring
717	+/// `entries_injection.dart`'s `entriesBoxName` pattern but split in two
718	+/// since each caches a structurally different DTO shape.
719	+const chatSessionsBoxName = 'chat_sessions';
720	+const chatMessagesBoxName = 'chat_messages';
721	+
722	+/// Registers the `chat` feature into the project's single `get_it`
723	+/// instance (`sl`) — mirrors `entries_injection.dart`'s pattern. Called
724	+/// from `setupCoreDependencies()` after `Hive.initFlutter()` has already
725	+/// run (Code Map), same ordering requirement `registerEntriesFeature()`
726	+/// documents for itself.
727	+Future<void> registerChatFeature() async {
728	+  final sessionsBox = await Hive.openBox<Map>(chatSessionsBoxName);
729	+  final messagesBox = await Hive.openBox<Map>(chatMessagesBoxName);
730	+  // `instanceName` disambiguates the two `Box<Map>` singletons from each
731	+  // other and from `entries_injection.dart`'s own unnamed one — `get_it`
732	+  // keys a registration by type + instance name, so three same-typed
733	+  // singletons coexist safely.
734	+  sl.registerSingleton<Box<Map>>(sessionsBox, instanceName: chatSessionsBoxName);
735	+  sl.registerSingleton<Box<Map>>(messagesBox, instanceName: chatMessagesBoxName);
736	+
737	+  sl.registerLazySingleton<ChatRemoteDataSource>(
738	+    () => ChatRemoteDataSource(sl<ApiClient>()),
739	+  );
740	+
741	+  sl.registerLazySingleton<ChatRepository>(
742	+    () => ChatRepositoryImpl(
743	+      remoteDataSource: sl<ChatRemoteDataSource>(),
744	+      sessionsBox: sl<Box<Map>>(instanceName: chatSessionsBoxName),
745	+      messagesBox: sl<Box<Map>>(instanceName: chatMessagesBoxName),
746	+    ),
747	+  );
748	+
749	+  // A `lazySingleton`, not a factory (Code Map), mirroring
750	+  // `MeusRegistrosCubit`: long-lived, so a session bootstrapped on one
751	+  // visit to Home/Chat survives leaving and returning within the same app
752	+  // session (`ChatCubit.init()`'s own no-op guard). `dispose:` wires
753	+  // `close()` into `get_it`'s own reset lifecycle, same convention every
754	+  // other long-lived cubit in this codebase already uses.
755	+  sl.registerLazySingleton<ChatCubit>(
756	+    () => ChatCubit(sl<ChatRepository>()),
757	+    dispose: (cubit) => cubit.close(),
758	+  );
759	+}
