776	+/// The chat feature's one remote data source — non-streaming calls go
777	+/// through `ApiClient`'s plain JSON methods exactly like
778	+/// `EntriesRemoteDataSource`'s own `create`/`list`/`get`; [sendMessage]
779	+/// alone goes through `ApiClient.postStream` and owns the one piece of
780	+/// SSE-specific logic this story introduces: splitting the raw byte
781	+/// stream into `event:`/`data:` blocks and mapping each into a
782	+/// [ChatStreamEvent] (or an in-band [Failure]) — kept feature-local per
783	+/// the Code Map, `ApiClient` itself knows nothing about the SSE grammar.
784	+class ChatRemoteDataSource {
785	+  ChatRemoteDataSource(this._apiClient);
786	+
787	+  final ApiClient _apiClient;
788	+
789	+  Future<Either<Failure, List<ChatSessionDto>>> listSessions() async {
790	+    final result = await _apiClient.get('chat-sessions-list');
791	+    return result.flatMap((json) {
792	+      try {
793	+        final data = json['data'] as List<dynamic>;
794	+        return right(
795	+          data
796	+              .map(
797	+                (item) => ChatSessionDto.fromJson(item as Map<String, dynamic>),
798	+              )
799	+              .toList(),
800	+        );
801	+      } catch (error) {
802	+        // A 200 response that doesn't match the expected shape is a
803	+        // client-side parse failure, never a backend-sent code — same
804	+        // RNF09 rationale `EntriesRemoteDataSource`'s own calls document.
805	+        return left(Failure.malformedResponse(message: error.toString()));
806	+      }
807	+    });
808	+  }
809	+
810	+  /// Sends no `title` (Boundaries: "`chat-sessions-create` with no
811	+  /// title") — the contract's own `title` field is optional
812	+  /// (`openapi.yaml`), an empty body is valid.
813	+  Future<Either<Failure, ChatSessionDto>> createSession() async {
814	+    final result = await _apiClient.post('chat-sessions-create', data: const {});
815	+    return result.flatMap((json) {
816	+      try {
817	+        final data = json['data'] as Map<String, dynamic>;
818	+        return right(ChatSessionDto.fromJson(data));
819	+      } catch (error) {
820	+        return left(Failure.malformedResponse(message: error.toString()));
821	+      }
822	+    });
823	+  }
824	+
825	+  Future<Either<Failure, List<ChatMessageDto>>> listMessages(
826	+    String sessionId,
827	+  ) async {
828	+    final result = await _apiClient.get(
829	+      'chat-messages-list',
830	+      pathParams: [sessionId],
831	+    );
832	+    return result.flatMap((json) {
833	+      try {
834	+        final data = json['data'] as List<dynamic>;
835	+        return right(
836	+          data
837	+              .map(
838	+                (item) => ChatMessageDto.fromJson(item as Map<String, dynamic>),
839	+              )
840	+              .toList(),
841	+        );
842	+      } catch (error) {
843	+        return left(Failure.malformedResponse(message: error.toString()));
844	+      }
845	+    });
846	+  }
847	+
848	+  /// Consumes `ApiClient.postStream('chat-messages-send', pathParams:
849	+  /// [sessionId], data: {'content': content})` chunk by chunk, buffering
850	+  /// raw text until a full `\n\n`-terminated SSE event block is
851	+  /// available, then hands each complete block to [_parseEvent].
852	+  ///
853	+  /// Terminal handling (Design Notes/I/O matrix):
854	+  /// - An upstream `Left` (an offline/timeout/etc. failure from the
855	+  ///   underlying HTTP call itself, surfaced by `ApiClient.postStream`) is
856	+  ///   forwarded as-is and ends the stream immediately — covers "Send
857	+  ///   while offline" (an immediate `Left(Failure.networkOffline)`, never
858	+  ///   queued) and any other transport-level failure.
859	+  /// - A parsed `done` event or an in-band `error` event (mapped via
860	+  ///   [Failure.fromCode]) both end the stream right after being emitted
861	+  ///   — the backend's own SSE ordering guarantees neither is followed by
862	+  ///   anything else worth reading.
863	+  /// - If the underlying byte stream simply ends (no exception, no
864	+  ///   `done`/`error` event ever parsed) — a mid-stream drop — a single
865	+  ///   trailing `Left(Failure.networkTimeout)` is emitted, since the
866	+  ///   closed, 13-code taxonomy has no dedicated "dropped stream" code
867	+  ///   (Design Notes).
868	+  Stream<Either<Failure, ChatStreamEvent>> sendMessage(
869	+    String sessionId,
870	+    String content,
871	+  ) async* {
872	+    var buffer = '';
873	+    await for (final chunkResult in _apiClient.postStream(
874	+      'chat-messages-send',
875	+      pathParams: [sessionId],
876	+      data: {'content': content},
877	+    )) {
878	+      final upstreamFailure = chunkResult.fold((f) => f, (_) => null);
879	+      if (upstreamFailure != null) {
880	+        yield left(upstreamFailure);
881	+        return;
882	+      }
883	+      final chunk = chunkResult.fold((_) => '', (s) => s);
884	+      buffer += chunk.replaceAll('\r\n', '\n');
885	+
886	+      var separatorIndex = buffer.indexOf('\n\n');
887	+      while (separatorIndex != -1) {
888	+        final rawEvent = buffer.substring(0, separatorIndex);
889	+        buffer = buffer.substring(separatorIndex + 2);
890	+        if (rawEvent.trim().isNotEmpty) {
891	+          final parsed = _parseEvent(rawEvent);
892	+          if (parsed != null) {
893	+            final isDone = parsed.fold((_) => false, (e) => e is ChatDoneEvent);
894	+            final isFailure = parsed.isLeft();
895	+            yield parsed;
896	+            // A `done`/in-band-error exit is a clean terminal event, not
897	+            // a drop — return directly, skipping the trailing
898	+            // mid-stream-drop failure below.
899	+            if (isDone || isFailure) {
900	+              return;
901	+            }
902	+          }
903	+        }
904	+        separatorIndex = buffer.indexOf('\n\n');
905	+      }
906	+    }
907	+    // Reached only if the byte stream ended on its own (no exception, no
908	+    // `done`/`error` event ever parsed) — a mid-stream drop.
909	+    yield left(
910	+      const Failure.networkTimeout(
911	+        message: 'Connection closed before the response completed',
912	+      ),
913	+    );
914	+  }
915	+
916	+  /// Parses one complete, blank-line-delimited SSE event block into a
917	+  /// [ChatStreamEvent] (`Right`), an in-band failure (`Left`), or `null`
918	+  /// when the block should simply be skipped — a `context` event
919	+  /// (Boundaries: "received and discarded", never surfaced as a
920	+  /// [ChatStreamEvent]) or any event name this client doesn't recognize
921	+  /// (forward-compatible: an unknown future event type is ignored rather
922	+  /// than treated as malformed). Any JSON-decode failure, or a decoded
923	+  /// payload missing the field a known event name requires, maps to
924	+  /// [Failure.malformedResponse] (Design Notes: "anything that fails to
925	+  /// parse as expected becomes `Failure.malformedResponse`, never a
926	+  /// crash") — never a thrown exception escaping into [sendMessage]'s own
927	+  /// `async*` body.
928	+  Either<Failure, ChatStreamEvent>? _parseEvent(String rawEvent) {
929	+    String? eventName;
930	+    final dataLines = <String>[];
931	+    for (final line in rawEvent.split('\n')) {
932	+      if (line.startsWith('event:')) {
933	+        eventName = line.substring('event:'.length).trim();
934	+      } else if (line.startsWith('data:')) {
935	+        var value = line.substring('data:'.length);
936	+        if (value.startsWith(' ')) {
937	+          value = value.substring(1);
938	+        }
939	+        dataLines.add(value);
940	+      }
941	+    }
942	+    if (eventName == null) {
943	+      return null;
944	+    }
945	+    final dataStr = dataLines.join('\n');
946	+
947	+    switch (eventName) {
948	+      case 'message_created':
949	+        try {
950	+          final json = jsonDecode(dataStr) as Map<String, dynamic>;
951	+          return right(ChatMessageCreatedEvent(json['id'] as String));
952	+        } catch (error) {
953	+          return left(
954	+            Failure.malformedResponse(
955	+              message: 'malformed message_created event: $error',
956	+            ),
957	+          );
958	+        }
959	+      case 'context':
960	+        // Boundaries: "never rendering the SSE `context` event's
961	+        // retrieval/citation data" — received and discarded.
962	+        return null;
963	+      case 'token':
964	+        try {
965	+          final json = jsonDecode(dataStr) as Map<String, dynamic>;
966	+          return right(ChatTokenEvent(json['delta'] as String));
967	+        } catch (error) {
968	+          return left(
969	+            Failure.malformedResponse(
970	+              message: 'malformed token event: $error',
971	+            ),
972	+          );
973	+        }
974	+      case 'done':
975	+        return right(const ChatDoneEvent());
976	+      case 'error':
977	+        try {
978	+          final json = jsonDecode(dataStr) as Map<String, dynamic>;
979	+          final code = json['code'] as String;
980	+          final message = json['message'];
981	+          return left(
982	+            Failure.fromCode(
983	+              code,
984	+              message is String ? message : 'Unknown error',
985	+            ),
986	+          );
987	+        } catch (error) {
988	+          return left(
989	+            Failure.malformedResponse(
990	+              message: 'malformed error event: $error',
991	+            ),
992	+          );
993	+        }
994	+      default:
995	+        // Forward-compatible: an event name this client doesn't
996	+        // recognize is skipped, not treated as malformed.
997	+        return null;
998	+    }
999	+  }
1000	+}
