2384	+  /// `pumpAndSettle()`) ever blocks on a bubble that finished streaming.
2385	+  void _syncCursorAnimation() {
2386	+    final shouldAnimate = widget.message.status == ChatMessageStatus.streaming;
2387	+    if (shouldAnimate && !_cursorController.isAnimating) {
